-- Synthetic demonstration data only. All objects are explicitly marked IsDemo.
SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF NOT EXISTS(SELECT 1 FROM dbo.Artists WHERE ArtistName=N'Nghệ sĩ minh họa Muses')
 INSERT INTO dbo.Artists(ArtistName,Biography) VALUES(N'Nghệ sĩ minh họa Muses',N'Nhân vật minh họa cho kiểm thử, không phải nghệ sĩ có thật.');
IF NOT EXISTS(SELECT 1 FROM dbo.Categories WHERE CategoryName=N'Nghiên cứu màu minh họa')
 INSERT INTO dbo.Categories(CategoryName,Description) VALUES(N'Nghiên cứu màu minh họa',N'Dữ liệu tự tạo để kiểm thử.');
IF NOT EXISTS(SELECT 1 FROM dbo.Materials WHERE Name=N'Đồ họa vector minh họa')
 INSERT INTO dbo.Materials(Name) VALUES(N'Đồ họa vector minh họa');
DECLARE @artist INT=(SELECT TOP(1) ArtistID FROM dbo.Artists WHERE ArtistName=N'Nghệ sĩ minh họa Muses');
DECLARE @category INT=(SELECT CategoryID FROM dbo.Categories WHERE CategoryName=N'Nghiên cứu màu minh họa');
DECLARE @material INT=(SELECT MaterialID FROM dbo.Materials WHERE Name=N'Đồ họa vector minh họa');
DECLARE @admin INT=(SELECT TOP(1) UserID FROM dbo.Users WHERE Role IN ('Admin','Administrator') AND IsActive=1 ORDER BY UserID);
IF @admin IS NULL THROW 51000,N'Create an Admin account before seeding.',1;
IF NOT EXISTS(SELECT 1 FROM dbo.Museums WHERE Name=N'Không gian minh họa Muses 1' AND IsDemo=1) INSERT INTO dbo.Museums(Name,Address,Description,Latitude,Longitude,IsPublic,PinVerified,Source,IsDemo) VALUES(N'Không gian minh họa Muses 1',N'Địa điểm minh họa tại Việt Nam — không phải địa chỉ bảo tàng có thật',N'Bảo tàng giả lập để kiểm thử bản đồ và lịch trưng bày.',10.8231,106.6297,1,1,N'Dữ liệu tự tạo cho kiểm thử, không phải nơi trưng bày thực tế.',1);
IF NOT EXISTS(SELECT 1 FROM dbo.Museums WHERE Name=N'Không gian minh họa Muses 2' AND IsDemo=1) INSERT INTO dbo.Museums(Name,Address,Description,Latitude,Longitude,IsPublic,PinVerified,Source,IsDemo) VALUES(N'Không gian minh họa Muses 2',N'Địa điểm minh họa tại Việt Nam — không phải địa chỉ bảo tàng có thật',N'Bảo tàng giả lập để kiểm thử bản đồ và lịch trưng bày.',21.0285,105.8542,1,1,N'Dữ liệu tự tạo cho kiểm thử, không phải nơi trưng bày thực tế.',1);
IF NOT EXISTS(SELECT 1 FROM dbo.Museums WHERE Name=N'Không gian minh họa Muses 3' AND IsDemo=1) INSERT INTO dbo.Museums(Name,Address,Description,Latitude,Longitude,IsPublic,PinVerified,Source,IsDemo) VALUES(N'Không gian minh họa Muses 3',N'Địa điểm minh họa tại Việt Nam — không phải địa chỉ bảo tàng có thật',N'Bảo tàng giả lập để kiểm thử bản đồ và lịch trưng bày.',16.0544,108.2022,1,1,N'Dữ liệu tự tạo cho kiểm thử, không phải nơi trưng bày thực tế.',1);
DECLARE @id INT,@created BIT;
SET @id=NULL; SET @created=0; SELECT @id=ArtworkID FROM dbo.Artworks WHERE ArtworkName=N'Nghiên cứu màu 01' AND IsDemo=1;
IF @id IS NULL BEGIN INSERT INTO dbo.Artworks(ArtworkName,ArtistID,CategoryID,MaterialID,Material,CreationPeriod,Dimensions,PublicationStatus,InformationSource,IsDemo) VALUES(N'Nghiên cứu màu 01',@artist,@category,@material,N'Đồ họa vector minh họa',N'2026',N'600 × 760 px','Draft',N'Nội dung và hình SVG tự tạo cho kiểm thử, không phải hiện vật có thật.',1); SET @id=SCOPE_IDENTITY(); SET @created=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.ArtworkDescriptions d JOIN dbo.Languages l ON l.LanguageID=d.LanguageID WHERE d.ArtworkID=@id AND l.LanguageCode='vi') INSERT INTO dbo.ArtworkDescriptions(ArtworkID,LanguageID,Title,FullDescription,PublicationStatus,InformationSource) SELECT @id,LanguageID,N'Nghiên cứu màu 01',N'Tác phẩm minh họa tự tạo gồm các mảng màu, đường cong và hình tròn. Đây là dữ liệu kiểm thử, không mô tả một hiện vật trong bảo tàng có thật.','Published',N'Bản dịch minh họa nhập thủ công; nhóm cần duyệt trước nghiệm thu.' FROM dbo.Languages WHERE LanguageCode='vi';
IF NOT EXISTS(SELECT 1 FROM dbo.ArtworkDescriptions d JOIN dbo.Languages l ON l.LanguageID=d.LanguageID WHERE d.ArtworkID=@id AND l.LanguageCode='en') INSERT INTO dbo.ArtworkDescriptions(ArtworkID,LanguageID,Title,FullDescription,PublicationStatus,InformationSource) SELECT @id,LanguageID,N'Colour study 01',N'This original demonstration study combines coloured fields, curves and a circle. It is test data and does not represent an object in a real museum.','Published',N'Bản dịch minh họa nhập thủ công; nhóm cần duyệt trước nghiệm thu.' FROM dbo.Languages WHERE LanguageCode='en';
IF NOT EXISTS(SELECT 1 FROM dbo.ArtworkDescriptions d JOIN dbo.Languages l ON l.LanguageID=d.LanguageID WHERE d.ArtworkID=@id AND l.LanguageCode='zh') INSERT INTO dbo.ArtworkDescriptions(ArtworkID,LanguageID,Title,FullDescription,PublicationStatus,InformationSource) SELECT @id,LanguageID,N'色彩习作 01',N'这幅原创示例作品由色块、曲线和圆形组成。这是测试数据，并不代表真实博物馆中的藏品。','Published',N'Bản dịch minh họa nhập thủ công; nhóm cần duyệt trước nghiệm thu.' FROM dbo.Languages WHERE LanguageCode='zh';
IF NOT EXISTS(SELECT 1 FROM dbo.ArtworkDescriptions d JOIN dbo.Languages l ON l.LanguageID=d.LanguageID WHERE d.ArtworkID=@id AND l.LanguageCode='ja') INSERT INTO dbo.ArtworkDescriptions(ArtworkID,LanguageID,Title,FullDescription,PublicationStatus,InformationSource) SELECT @id,LanguageID,N'色彩の習作 01',N'このオリジナルのデモ作品は、色面、曲線、円を組み合わせています。テスト用データであり、実在する美術館の収蔵品を示すものではありません。','Published',N'Bản dịch minh họa nhập thủ công; nhóm cần duyệt trước nghiệm thu.' FROM dbo.Languages WHERE LanguageCode='ja';
IF NOT EXISTS(SELECT 1 FROM dbo.ArtworkDescriptions d JOIN dbo.Languages l ON l.LanguageID=d.LanguageID WHERE d.ArtworkID=@id AND l.LanguageCode='ko') INSERT INTO dbo.ArtworkDescriptions(ArtworkID,LanguageID,Title,FullDescription,PublicationStatus,InformationSource) SELECT @id,LanguageID,N'색채 습작 01',N'직접 만든 이 시연 작품은 색면, 곡선과 원으로 구성되어 있습니다. 실제 박물관의 소장품을 나타내지 않는 테스트 데이터입니다.','Published',N'Bản dịch minh họa nhập thủ công; nhóm cần duyệt trước nghiệm thu.' FROM dbo.Languages WHERE LanguageCode='ko';
IF NOT EXISTS(SELECT 1 FROM dbo.ArtworkImages WHERE ArtworkID=@id) INSERT INTO dbo.ArtworkImages(ArtworkID,ImageURL,IsPrimary,DisplayOrder) VALUES(@id,'/images/background/catalog-demo/01.svg',1,1);
UPDATE dbo.Artworks SET PublicationStatus='Published',ImageSource=N'Hình SVG tự tạo bởi Muses cho kiểm thử, được phép dùng trong đồ án.' WHERE ArtworkID=@id AND IsDemo=1 AND @created=1;
IF NOT EXISTS(SELECT 1 FROM dbo.DisplaySchedules WHERE ArtworkID=@id) INSERT INTO dbo.DisplaySchedules(ArtworkID,MuseumID,StartDate,Status,Source,VerifiedOn,UpdatedBy) SELECT @id,MuseumID,CONVERT(date,DATEADD(minute,420,SYSUTCDATETIME())),'Confirmed',N'Lịch giả lập phục vụ kiểm thử, không phải thông tin trưng bày thật.',CONVERT(date,DATEADD(minute,420,SYSUTCDATETIME())),@admin FROM dbo.Museums WHERE Name=N'Không gian minh họa Muses 1' AND IsDemo=1;
