SET @id=NULL; SET @created=0; SELECT @id=ArtworkID FROM dbo.Artworks WHERE ArtworkName=N'Nghiên cứu màu 05' AND IsDemo=1;
IF @id IS NULL BEGIN INSERT INTO dbo.Artworks(ArtworkName,ArtistID,CategoryID,MaterialID,Material,CreationPeriod,Dimensions,PublicationStatus,InformationSource,IsDemo) VALUES(N'Nghiên cứu màu 05',@artist,@category,@material,N'Đồ họa vector minh họa',N'2026',N'600 × 760 px','Draft',N'Nội dung và hình SVG tự tạo cho kiểm thử, không phải hiện vật có thật.',1); SET @id=SCOPE_IDENTITY(); SET @created=1; END;
IF NOT EXISTS(SELECT 1 FROM dbo.ArtworkDescriptions d JOIN dbo.Languages l ON l.LanguageID=d.LanguageID WHERE d.ArtworkID=@id AND l.LanguageCode='vi') INSERT INTO dbo.ArtworkDescriptions(ArtworkID,LanguageID,Title,FullDescription,PublicationStatus,InformationSource) SELECT @id,LanguageID,N'Nghiên cứu màu 05',N'Tác phẩm minh họa tự tạo gồm các mảng màu, đường cong và hình tròn. Đây là dữ liệu kiểm thử, không mô tả một hiện vật trong bảo tàng có thật.','Published',N'Bản dịch minh họa nhập thủ công; nhóm cần duyệt trước nghiệm thu.' FROM dbo.Languages WHERE LanguageCode='vi';
IF NOT EXISTS(SELECT 1 FROM dbo.ArtworkDescriptions d JOIN dbo.Languages l ON l.LanguageID=d.LanguageID WHERE d.ArtworkID=@id AND l.LanguageCode='en') INSERT INTO dbo.ArtworkDescriptions(ArtworkID,LanguageID,Title,FullDescription,PublicationStatus,InformationSource) SELECT @id,LanguageID,N'Colour study 05',N'This original demonstration study combines coloured fields, curves and a circle. It is test data and does not represent an object in a real museum.','Published',N'Bản dịch minh họa nhập thủ công; nhóm cần duyệt trước nghiệm thu.' FROM dbo.Languages WHERE LanguageCode='en';
IF NOT EXISTS(SELECT 1 FROM dbo.ArtworkDescriptions d JOIN dbo.Languages l ON l.LanguageID=d.LanguageID WHERE d.ArtworkID=@id AND l.LanguageCode='zh') INSERT INTO dbo.ArtworkDescriptions(ArtworkID,LanguageID,Title,FullDescription,PublicationStatus,InformationSource) SELECT @id,LanguageID,N'色彩习作 05',N'这幅原创示例作品由色块、曲线和圆形组成。这是测试数据，并不代表真实博物馆中的藏品。','Published',N'Bản dịch minh họa nhập thủ công; nhóm cần duyệt trước nghiệm thu.' FROM dbo.Languages WHERE LanguageCode='zh';
IF NOT EXISTS(SELECT 1 FROM dbo.ArtworkDescriptions d JOIN dbo.Languages l ON l.LanguageID=d.LanguageID WHERE d.ArtworkID=@id AND l.LanguageCode='ja') INSERT INTO dbo.ArtworkDescriptions(ArtworkID,LanguageID,Title,FullDescription,PublicationStatus,InformationSource) SELECT @id,LanguageID,N'色彩の習作 05',N'このオリジナルのデモ作品は、色面、曲線、円を組み合わせています。テスト用データであり、実在する美術館の収蔵品を示すものではありません。','Published',N'Bản dịch minh họa nhập thủ công; nhóm cần duyệt trước nghiệm thu.' FROM dbo.Languages WHERE LanguageCode='ja';
IF NOT EXISTS(SELECT 1 FROM dbo.ArtworkDescriptions d JOIN dbo.Languages l ON l.LanguageID=d.LanguageID WHERE d.ArtworkID=@id AND l.LanguageCode='ko') INSERT INTO dbo.ArtworkDescriptions(ArtworkID,LanguageID,Title,FullDescription,PublicationStatus,InformationSource) SELECT @id,LanguageID,N'색채 습작 05',N'직접 만든 이 시연 작품은 색면, 곡선과 원으로 구성되어 있습니다. 실제 박물관의 소장품을 나타내지 않는 테스트 데이터입니다.','Published',N'Bản dịch minh họa nhập thủ công; nhóm cần duyệt trước nghiệm thu.' FROM dbo.Languages WHERE LanguageCode='ko';
IF NOT EXISTS(SELECT 1 FROM dbo.ArtworkImages WHERE ArtworkID=@id) INSERT INTO dbo.ArtworkImages(ArtworkID,ImageURL,IsPrimary,DisplayOrder) VALUES(@id,'/images/background/catalog-demo/05.svg',1,1);
